PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR CONSTANT
    HI : INT := 90;
    LO : INT := 10;
END_VAR

IF Level >= HI THEN
    PumpIn := FALSE;
    ValveOut := TRUE;
ELSIF Level <= LO THEN
    PumpIn := TRUE;
    ValveOut := FALSE;
ELSE
    PumpIn := FALSE;
    ValveOut := FALSE;
END_IF;

END_PROGRAM

