PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL;
    OpenB_Cmd : BOOL;
END_VAR
VAR_OUTPUT
    DoorA : BOOL;
    DoorB : BOOL;
END_VAR

IF OpenA_Cmd THEN
    DoorA := TRUE;
ELSE
    DoorA := FALSE;
END_IF;

IF OpenB_Cmd AND NOT DoorA THEN
    DoorB := TRUE;
ELSE
    DoorB := FALSE;
END_IF;

END_PROGRAM

