PROGRAM tank_cycle
VAR_INPUT
    Level : INT;
    StartCycle : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    Pump : BOOL;
    Valve : BOOL;
END_VAR
VAR CONSTANT
    LOW : INT := 10;
    HIGH : INT := 90;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    IDLE : INT := 0;
    FILLING : INT := 1;
    DRAINING : INT := 2;
END_VAR

IF NOT EStop THEN
    State := IDLE;
ELSIF StartCycle AND Level < HIGH THEN
    State := FILLING;
ELSIF Level >= HIGH THEN
    State := DRAINING;
END_IF;

CASE State OF
    IDLE:
        Pump := FALSE;
        Valve := FALSE;
    FILLING:
        Pump := TRUE;
        Valve := FALSE;
    DRAINING:
        Pump := FALSE;
        Valve := Level > LOW;
END_CASE;

END_PROGRAM

