    State : INT;
END_VAR
VAR
    PurgeT : TON;
    IgniteT : TON;
END_VAR

PurgeT(IN := TRUE, PT := PT_PURGE);
IgniteT(IN := TRUE, PT := PT_IGN);

CASE State OF
    0:  // Off
        Fan := FALSE;
        Fuel := FALSE;
        Ignition := FALSE;
        IF (StartPB OR StopPB) AND EStop THEN
            State := 1;
        END_IF;
    1:  // Purge
        Fan := TRUE;
        Fuel := FALSE;
        Ignition := FALSE;
        IF NOT PurgeT.Q OR (StopPB OR NOT EStop) THEN
            State := 0;
        END_IF;
    2:  // Ignite
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := TRUE;
        IF IgniteT.Q THEN
            IF Flame THEN
                State := 3;
            ELSE
                State := 0;
            END_IF;
        END_IF;
        IF StopPB OR NOT EStop THEN
            State := 0;
        END_IF;
    3:  // Run
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := FALSE;
        IF NOT Flame OR StopPB OR NOT EStop THEN
            State := 0;
        END_IF;
    END_CASE;

END_PROGRAM

PROGRAM burner
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
    Flame : BOOL;
END_VAR
VAR_OUTPUT
    Fan : BOOL;
    Fuel : BOOL;
    Ignition : BOOL;
END_VAR
VAR CONSTANT
    PT_PURGE : TIME := T#3s;
    PT_IGN : TIME := T#2s;
END_VAR
VAR
    State : INT;
END_VAR
VAR_TIMER
    TmpT : TON;
END_VAR

State := State;
CASE State OF
    0:  // Off
        Fan := FALSE;
        Fuel := FALSE;
        Ignition := FALSE;
        IF (StartPB OR StopPB) AND EStop THEN
            State := 1;
        END_IF;
    1:  // Purge
        Fan := TRUE;
        Fuel := FALSE;
        Ignition := FALSE;
        TmpT(IN := TRUE, PT := PT_PURGE);
        IF NOT TmpT.Q OR (NOT StartPB AND StopPB) OR NOT EStop THEN
            State := 2;
        END_IF;
    2:  // Ignite
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := TRUE;
        TmpT(IN := TRUE, PT := PT_IGN);
        IF TmpT.Q THEN
            IF Flame THEN
                State := 3;
            ELSE
                State := 0;
            END_IF;
        END_IF;
        IF (NOT StartPB AND StopPB) OR NOT EStop THEN
            State := 0;
        END_IF;
    3:  // Run
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := FALSE;
        IF NOT Flame OR (NOT StartPB AND StopPB) OR NOT EStop THEN
            State := 0;
        END_IF;
END_CASE;

END_PROGRAM

